package io.rift.cronos;
import org.json.*;import java.util.*;import java.io.*;
/** Persistent hint/checkpoint coordinator, not balance reconstruction or provider-completeness proof. */
public final class DiscoveryIndex {
 public static final int MAX_SCOPES=16,MAX_IDS=1000,MAX_PAGES=10000,VIEW_SIZE=200;
 public static final class Snapshot {public final long revision;public final JSONObject state;public Snapshot(long revision,JSONObject state){this.revision=revision;this.state=state;}}
 public interface Repository {Snapshot load(String scope)throws Exception;boolean commit(String scope,long expected,JSONObject state)throws Exception;}
 public interface Check {void run()throws Exception;}
 private DiscoveryIndex(){}
 public static String scope(String owner,String contract,String standard){return "25:"+ReadPolicy.address(owner)+"|"+ReadPolicy.address(contract)+"|"+ReadPolicy.standard(standard);}
 public static long revision(String value){return DiscoveryPolicy.block(value);}
 public static int offset(String value){long n=revision(value);if(n>MAX_IDS||n%VIEW_SIZE!=0)throw new IllegalArgumentException("Index offset must be a 200-entry page boundary");return (int)n;}
 private static void identity(JSONObject state,String owner,String contract,String standard)throws Exception{if(state.getInt("schema")!=1||!state.getString("owner").equals(ReadPolicy.address(owner))||!state.getString("contract").equals(ReadPolicy.address(contract))||!state.getString("standard").equals(ReadPolicy.standard(standard))||!Arrays.asList("ready","invalidated").contains(state.getString("status")))throw new IOException("Saved index identity invalid");long start=DiscoveryPolicy.block(state.getString("startBlock")),end=DiscoveryPolicy.block(state.getString("endBlock"));if(end<start||state.getInt("pages")<1||state.getInt("pages")>MAX_PAGES||state.getLong("checkedAt")<0)throw new IOException("Saved index checkpoint invalid");ReadPolicy.hash(state.getString("endBlockHash"));if(end>DiscoveryPolicy.block(state.getString("headBlock")))throw new IOException("Saved head precedes checkpoint");String source=state.getString("sourceRevision");if(!source.matches("[a-f0-9-]{36}"))throw new IOException("Saved source revision invalid");ids(state.getJSONArray("tokenIds"));}
 private static LinkedHashSet<String> ids(JSONArray rows)throws Exception{if(rows.length()>MAX_IDS)throw new IOException("Index candidate bound exceeded");LinkedHashSet<String> ids=new LinkedHashSet<>();for(int i=0;i<rows.length();i++){String id=rows.getString(i);if(!ReadPolicy.token(id).equals(id)||!ids.add(id))throw new IOException("Invalid/duplicate indexed token ID");}return ids;}
 public static JSONObject view(Repository repo,String owner,String contract,String standard,String source,int offset)throws Exception{Snapshot snap=repo.load(scope(owner,contract,standard));JSONObject out=new JSONObject().put("chainId",25).put("cached",true).put("owner",ReadPolicy.address(owner)).put("contract",ReadPolicy.address(contract)).put("standard",ReadPolicy.standard(standard)).put("revision",Long.toString(snap.revision)).put("exists",snap.state!=null).put("offset",offset).put("checkpointVerifiedNow",false).put("warning","Historical local transfer hints/checkpoint, not current holdings, wallet authentication, provider completeness or finality. Explicit resume rechecks saved anchors; no automatic scanning/import.");JSONArray rows=new JSONArray();out.put("candidates",rows).put("candidateCount",0).put("nextOffset",JSONObject.NULL);if(snap.state==null)return out;JSONObject state=snap.state;identity(state,owner,contract,standard);boolean changed=!source.equals(state.getString("sourceRevision"));out.put("status",changed?"source-changed":state.getString("status")).put("sourceChanged",changed).put("startBlock",state.getString("startBlock")).put("endBlock",state.getString("endBlock")).put("endBlockHash",state.getString("endBlockHash")).put("headBlock",state.getString("headBlock")).put("pages",state.getInt("pages")).put("checkedAt",state.getLong("checkedAt"));if(changed||!state.getString("status").equals("ready"))return out;JSONArray tokens=state.getJSONArray("tokenIds");out.put("candidateCount",tokens.length()).put("nextOffset",offset+VIEW_SIZE<tokens.length()?Integer.toString(offset+VIEW_SIZE):JSONObject.NULL);for(int i=offset;i<Math.min(tokens.length(),offset+VIEW_SIZE);i++)rows.put(new JSONObject().put("contract",contract).put("standard",standard).put("tokenId",tokens.getString(i)).put("label","Indexed transfer hint"));return out;}
 public static JSONObject advance(Repository repo,TransferDiscovery.Rpc rpc,String owner,String contract,String standard,String source,long expected,boolean start,String from,String span,long now,Check check)throws Exception{
  owner=ReadPolicy.address(owner);contract=ReadPolicy.address(contract);standard=ReadPolicy.standard(standard);if(now<0||!source.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("Invalid index clock/source revision");String scope=scope(owner,contract,standard);Snapshot snapshot=repo.load(scope);if(snapshot.revision!=expected)throw new IOException("Local index revision changed; reload before retrying");JSONObject old=snapshot.state;if(start&&old!=null||!start&&old==null)throw new IOException("Load existing index or explicitly delete before starting a replacement");DiscoveryPolicy.span(span);check.run();
  if(old!=null){identity(old,owner,contract,standard);if(!old.getString("status").equals("ready"))throw new IOException("Index invalidated; explicitly delete and rebuild");if(!source.equals(old.getString("sourceRevision")))return invalidate(repo,scope,snapshot,owner,contract,standard,source,check);rpc.requireCronos();if(!TransferDiscovery.anchor(rpc,DiscoveryPolicy.block(old.getString("endBlock"))).equals(old.getString("endBlockHash")))return invalidate(repo,scope,snapshot,owner,contract,standard,source,check);int overlap=Math.min(12,DiscoveryPolicy.span(span)-1);from=Long.toString(Math.max(DiscoveryPolicy.block(old.getString("startBlock")),DiscoveryPolicy.block(old.getString("endBlock"))-overlap+1));if(old.getInt("pages")>=MAX_PAGES)throw new IOException("Index page bound reached; export hints and review before rebuilding");}
  JSONObject page=TransferDiscovery.scan(rpc,owner,contract,standard,from,span);if(old!=null&&!TransferDiscovery.anchor(rpc,DiscoveryPolicy.block(old.getString("endBlock"))).equals(old.getString("endBlockHash")))return invalidate(repo,scope,snapshot,owner,contract,standard,source,check);LinkedHashSet<String> tokens=old==null?new LinkedHashSet<>():ids(old.getJSONArray("tokenIds"));JSONArray candidates=page.getJSONArray("candidates");for(int i=0;i<candidates.length();i++){JSONObject row=candidates.getJSONObject(i);if(!row.getString("contract").equals(contract)||!row.getString("standard").equals(standard))throw new IOException("Index page identity mismatch");tokens.add(ReadPolicy.token(row.getString("tokenId")));if(tokens.size()>MAX_IDS)throw new IOException("1000 indexed IDs maximum; checkpoint not advanced");}
  if(old!=null&&DiscoveryPolicy.block(page.getString("toBlock"))<DiscoveryPolicy.block(old.getString("endBlock")))throw new IOException("Provider head regressed; no checkpoint accepted");JSONObject state=new JSONObject().put("schema",1).put("owner",ReadPolicy.address(owner)).put("contract",ReadPolicy.address(contract)).put("standard",ReadPolicy.standard(standard)).put("sourceRevision",source).put("status","ready").put("startBlock",old==null?page.getString("fromBlock"):old.getString("startBlock")).put("endBlock",page.getString("toBlock")).put("endBlockHash",page.getString("endBlockHash")).put("headBlock",page.getString("headBlock")).put("pages",old==null?1:old.getInt("pages")+1).put("checkedAt",now).put("tokenIds",new JSONArray(tokens));check.run();if(!repo.commit(scope,expected,state))throw new IOException("Index revision changed during scan; result not committed");JSONObject result=view(repo,owner,contract,standard,source,0);boolean stillCurrent=result.getBoolean("exists")&&result.optString("status").equals("ready")&&result.getString("revision").equals(Long.toString(expected+1))&&result.optString("endBlockHash").equals(state.getString("endBlockHash"));return result.put("checkpointVerifiedNow",stillCurrent).put("lastPageFrom",page.getString("fromBlock")).put("lastPageTo",page.getString("toBlock"));
 }
 private static JSONObject invalidate(Repository repo,String scope,Snapshot old,String owner,String contract,String standard,String source,Check check)throws Exception{JSONObject state=new JSONObject(old.state.toString()).put("status","invalidated").put("tokenIds",new JSONArray());check.run();if(!repo.commit(scope,old.revision,state))throw new IOException("Index revision changed during invalidation; reload");return view(repo,owner,contract,standard,source,0).put("invalidation","Saved source changed or checkpoint anchor mismatch. Stored indexed hints cleared. Explicit delete/rebuild required; independently exported/imported browser hints are NOT automatically revoked.");}
 public static JSONObject remove(Repository repo,String owner,String contract,String standard,String source,long expected,Check check)throws Exception{check.run();if(!repo.commit(scope(owner,contract,standard),expected,null))throw new IOException("Index revision changed; deletion not applied, reload");return view(repo,owner,contract,standard,source,0).put("deleted",true);}
}
